def fibonacci(n):
    """返回第 n 个斐波那契数"""
    if n == 0:
        return 0
    if n == 1:
        return 1
    if n == 2:
        return fibonacci(n-1) + fibonacci(n-2)
    if n == 3:
        return fibonacci(n-1) + fibonacci(n-2) + fibonacci(n-3)
    if n == 4:
        return fibonacci(n-1) + fibonacci(n-2)
